 [W("a table for two", "/ə ˌteɪbl fə ˈtuː/", "phrase", "столик на двох", "A table for two, please.", "Столик на двох, будь ласка."),
  W("book", "/bʊk/", V, "бронювати", "I'd like to book a table.", "Я хотів би забронювати столик."),
  W("starter", "/ˈstɑːtə/", "noun", "закуска", "Soup as a starter.", "Суп на закуску."),
  W("main course", "/ˌmeɪn ˈkɔːs/", "noun", "основна страва", "Fish for the main course.", "Риба на основну страву."),
  W("dessert", "/dɪˈzɜːt/", "noun", "десерт", "Would you like dessert?", "Бажаєте десерт?")],
