  fb("Tomato soup is a ___. Steak is a main course.", ["starter", "dessert", "table"], "Суп — starter."),
  bs("Столик на двох, будь ласка.", ["A", "table", "for", "two", "please"], ["to", "book"], "A table for two, please."),
