  liu("Could we have some more bread, please?", "Прослухайте. Що просять гості?", ["Ще хліба", "Ще води", "Рахунок"], "Some more bread."),
  mcu("Чим їдять суп?", ["spoon", "fork", "knife"], "A spoon — ложка."),
  fb("Could I have a clean ___? This one is dirty.", ["plate", "sauce", "ice"], "A clean plate."),
  fb("Excuse me, this knife ___ dirty.", ["is", "does", "have"], "This knife is dirty."),
  mc("Як правильно почати скаргу?", ["Excuse me, …", "Hello you, …", "Sorry me, …"], "Excuse me."),
  bs("Можна мені серветку, будь ласка?", ["Could", "I", "have", "a", "napkin", "please"], ["an"], "Could I have a napkin, please?"),
  tr("Мій суп холодний.", ["My soup is cold"], "My soup is cold."),
